import { getVercelOidcToken } from '@vercel/oidc';
import { createConnectErrorFromResponse, } from './token.js';
import { resolveBaseUrl } from './internal/base-url.js';
/**
 * Fetch a connector's metadata from Vercel Connect.
 *
 * Authenticates with the deployment's Vercel OIDC token (same as
 * {@link getToken}); the connector must be attached to the requesting
 * deployment's project and enabled for its environment.
 *
 * @param connector - The connector id or UID.
 */
export async function getConnectorMetadata(connector, options) {
    const vercelToken = options?.vercelToken ?? (await getVercelOidcToken());
    const baseUrl = resolveBaseUrl(options);
    const endpoint = `${baseUrl}/v1/connect/connectors/${encodeURIComponent(connector)}`;
    const response = await fetch(endpoint, {
        method: 'GET',
        headers: {
            Accept: 'application/json',
            Authorization: `Bearer ${vercelToken}`,
        },
    });
    if (!response.ok) {
        throw await createConnectErrorFromResponse(response, 'Failed to get connector');
    }
    const { data, ...rest } = (await response.json());
    return { ...rest, vendor: data ?? {} };
}
